root=Path.cwd(); private=json.loads(Path('C:/Users/SIMJAE/AppData/Local/Temp/bayada-synthetic-qa-private.json').read_text()); fixtures=json.loads((root/'output/korea-qa-fixtures.json').read_text()); evidence=[]; note="UI 검증 "+str(time.time_ns()); article="QA UI editor "+str(time.time_ns())
